func (sp *ServerParams) Defaults() {
}

func (sp *ServerParams) ShouldDisplay(field string) bool {
	sp.K8s.server = sp.Server
	switch field {
	case "K8s":
		return sp.Server == Kube || sp.Server == Astera
	case "SSH": // the Kube and Astera commands run locally
		return sp.Server != Kube && sp.Server != Astera
	default:
		return true
	}
}

